:root {
  --ink: #171910;
  --ink-soft: #25281d;
  --parchment: #e9dfc4;
  --parchment-dim: #c9bd9f;
  --gold: #c7a96b;
  --gold-bright: #e6cd92;
  --gold-dim: #806c43;
  --french: #315f9e;
  --french-bright: #6f9dd8;
  --british: #9a3f35;
  --british-bright: #d17668;
  --green: #7e8d58;
  --line: rgba(224, 208, 172, .18);
  --serif: "Palatino Linotype", "Book Antiqua", Palatino, Georgia, "Times New Roman", serif;
  --sans: "Gill Sans", "Gill Sans MT", Calibri, "Trebuchet MS", sans-serif;
}

* { box-sizing: border-box; }
html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #11140e;
  color: var(--parchment);
  font-family: var(--serif);
  -webkit-font-smoothing: antialiased;
  overscroll-behavior: none;
}
button { font: inherit; color: inherit; }
button:focus-visible { outline: 1px solid var(--gold-bright); outline-offset: 3px; }
.hidden { display: none !important; }

#app, #battlefield {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
}
#battlefield {
  display: block;
  cursor: crosshair;
  touch-action: none;
}
#battlefield.panning { cursor: grabbing; }
#battlefield.over-unit { cursor: pointer; }
#battlefield.ordering { cursor: cell; }

.grade, .grain {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 2;
}
.grade {
  background:
    radial-gradient(ellipse at 52% 42%, transparent 37%, rgba(13, 16, 10, .17) 75%, rgba(7, 9, 5, .56) 115%),
    linear-gradient(to bottom, rgba(211, 187, 129, .055), transparent 24%, transparent 76%, rgba(11, 15, 8, .19));
  mix-blend-mode: multiply;
}
.grain {
  opacity: .13;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 140 140' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.78' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.7'/%3E%3C/svg%3E");
  mix-blend-mode: soft-light;
}

#hud {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 10;
  user-select: none;
  -webkit-user-select: none;
}
#hud > * { pointer-events: auto; }

.topbar {
  position: absolute;
  top: max(16px, env(safe-area-inset-top));
  left: max(18px, env(safe-area-inset-left));
  right: max(18px, env(safe-area-inset-right));
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  pointer-events: none !important;
}
.topbar > * { pointer-events: auto; }

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 315px;
  filter: drop-shadow(0 2px 5px rgba(0,0,0,.5));
}
.crest {
  width: 48px;
  height: 54px;
  color: var(--gold);
  padding: 3px;
  border: 1px solid rgba(199,169,107,.35);
  background: rgba(16,19,12,.55);
  backdrop-filter: blur(5px);
  display: grid;
  place-items: center;
}
.crest svg { width: 40px; height: 40px; }
.brand-type { line-height: 1; }
.eyebrow {
  display: block;
  color: var(--gold);
  font-family: var(--sans);
  font-size: 8px;
  letter-spacing: .32em;
  text-transform: uppercase;
  margin-bottom: 4px;
}
.brand h1 {
  font-size: 28px;
  font-weight: 500;
  letter-spacing: .02em;
  margin: 0;
  color: #f2ead6;
  text-shadow: 0 1px 0 #000, 0 3px 12px rgba(0,0,0,.6);
}
.brand h1 i {
  color: var(--gold);
  font-size: .7em;
  font-style: normal;
}
.place {
  display: block;
  font-family: var(--sans);
  font-size: 9px;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: rgba(233,223,196,.58);
  margin-top: 5px;
}

.objective {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  top: 2px;
  width: min(340px, 30vw);
  text-align: center;
  text-shadow: 0 1px 3px #000;
}
.obj-kicker {
  font-family: var(--sans);
  color: var(--gold);
  font-size: 8px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: .3em;
  display: block;
  margin-bottom: 3px;
}
.objective strong {
  font-size: 17px;
  letter-spacing: .035em;
  font-weight: 500;
  color: #f3ead3;
}
.obj-track {
  height: 2px;
  background: rgba(232,219,187,.16);
  margin: 8px auto 6px;
  position: relative;
  overflow: hidden;
}
.obj-track:before, .obj-track:after {
  content: "";
  position: absolute;
  top: -2px;
  width: 5px; height: 5px;
  background: var(--gold-dim);
  transform: rotate(45deg);
  z-index: 2;
}
.obj-track:before { left: 0; }
.obj-track:after { right: 0; }
.obj-track i {
  display: block;
  height: 100%;
  width: 18%;
  background: linear-gradient(90deg, #836d3f, var(--gold-bright));
  box-shadow: 0 0 9px rgba(214,181,109,.55);
  transition: width .6s ease;
}
.obj-status {
  font-family: var(--sans);
  font-size: 8.5px;
  letter-spacing: .08em;
  color: rgba(233,223,196,.63);
}

.top-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  filter: drop-shadow(0 2px 6px rgba(0,0,0,.35));
}
.round-btn {
  width: 34px; height: 34px;
  display: grid; place-items: center;
  border: 1px solid rgba(214,194,151,.28);
  background: rgba(19,23,15,.68);
  color: rgba(236,226,201,.8);
  backdrop-filter: blur(6px);
  cursor: pointer;
  transition: border-color .18s, background .18s, color .18s;
}
.round-btn:hover { border-color: rgba(230,205,146,.7); background: rgba(38,42,29,.8); color: #fff3d8; }
.round-btn svg { width: 17px; height: 17px; }
.round-btn.muted { color: rgba(236,226,201,.32); }
.pause { position: relative; }
.pause-x {
  position: absolute; inset: 0;
  display: grid; place-items: center;
  font-family: var(--sans); font-size: 13px;
}
.pause.paused svg { display: none; }
.speed-group {
  display: flex;
  border: 1px solid rgba(214,194,151,.24);
  background: rgba(19,23,15,.62);
  backdrop-filter: blur(6px);
}
.speed-group button {
  border: 0;
  background: transparent;
  color: rgba(236,226,201,.45);
  font-family: var(--sans);
  font-size: 10px;
  width: 29px; height: 32px;
  cursor: pointer;
}
.speed-group button + button { border-left: 1px solid rgba(214,194,151,.13); }
.speed-group button.active { background: rgba(199,169,107,.18); color: var(--gold-bright); }
.speed-group button:hover { color: #fff3d8; }

.field-orders {
  position: absolute;
  left: max(18px, env(safe-area-inset-left));
  top: 93px;
  width: 290px;
  padding: 9px 13px 10px 15px;
  border-left: 2px solid rgba(199,169,107,.55);
  background: linear-gradient(90deg, rgba(15,18,11,.55), rgba(15,18,11,.12));
  backdrop-filter: blur(3px);
  transition: opacity .7s;
}
.field-orders.quiet { opacity: .35; }
.order-label {
  font-family: var(--sans);
  font-size: 7.5px;
  letter-spacing: .27em;
  text-transform: uppercase;
  color: var(--gold);
}
.field-orders p {
  font-size: 11px;
  line-height: 1.45;
  margin: 5px 0 0;
  color: rgba(232,223,202,.74);
  font-style: italic;
}

.message-stack {
  position: absolute;
  top: 101px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  width: 400px;
  pointer-events: none !important;
}
.message {
  background: rgba(13,16,10,.72);
  border: 1px solid rgba(199,169,107,.26);
  padding: 6px 15px 6px 14px;
  color: #eee3c7;
  font-family: var(--sans);
  font-size: 9px;
  letter-spacing: .12em;
  text-transform: uppercase;
  animation: msg-in .35s ease both, msg-out .6s ease 4.2s forwards;
  backdrop-filter: blur(5px);
  white-space: nowrap;
}
.message b { color: var(--gold-bright); font-weight: 600; }
.message.warn { border-color: rgba(159,67,55,.55); }
.message.warn b { color: #e1937e; }
@keyframes msg-in { from { opacity: 0; transform: translateY(-6px); } }
@keyframes msg-out { to { opacity: 0; transform: translateY(-4px); } }

.battle-card {
  position: absolute;
  top: 92px;
  right: max(18px, env(safe-area-inset-right));
  width: 190px;
  background: linear-gradient(145deg, rgba(20,24,15,.82), rgba(13,16,10,.6));
  border: 1px solid rgba(214,194,151,.16);
  backdrop-filter: blur(7px);
  padding: 10px 12px 9px;
  box-shadow: 0 10px 30px rgba(0,0,0,.18);
}
.battle-card-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-family: var(--sans);
  font-size: 8px;
  letter-spacing: .15em;
  text-transform: uppercase;
  color: rgba(233,223,196,.55);
}
.battle-card-top b { color: var(--gold); font-weight: 500; font-family: var(--serif); letter-spacing: .05em; font-size: 10px; text-transform: none; }
.dual-bar {
  margin-top: 8px;
  height: 4px;
  display: flex;
  background: #39251e;
  position: relative;
}
.dual-bar i:first-child { width: 70%; background: linear-gradient(90deg, #284a7b, #6d9ad2); }
.dual-bar i:last-child { flex: 1; background: linear-gradient(90deg, #9a4438, #6f2924); }
.dual-labels {
  display: flex;
  justify-content: space-between;
  font-family: var(--sans);
  font-size: 7px;
  color: rgba(233,223,196,.42);
  letter-spacing: .12em;
  text-transform: uppercase;
  margin-top: 4px;
}
.battle-meta {
  margin-top: 7px;
  border-top: 1px solid rgba(214,194,151,.1);
  padding-top: 6px;
  display: flex;
  gap: 7px;
  font-family: var(--sans);
  font-size: 8px;
  letter-spacing: .08em;
  color: rgba(233,223,196,.42);
  text-transform: uppercase;
}
.battle-meta span:first-child { color: #e3d5b5; }

.crosshair-hint {
  position: absolute;
  left: 50%;
  bottom: 178px;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 5px 11px;
  border: 1px solid rgba(214,194,151,.12);
  background: rgba(13,16,10,.42);
  color: rgba(233,223,196,.5);
  font-family: var(--sans);
  font-size: 8px;
  letter-spacing: .12em;
  text-transform: uppercase;
  pointer-events: none !important;
  opacity: 0;
  transition: opacity .4s;
}
.crosshair-hint.show { opacity: 1; }
.mouse-icon {
  width: 8px; height: 11px;
  border: 1px solid currentColor;
  border-radius: 5px;
  position: relative;
}
.mouse-icon:after {
  content: ""; position: absolute; top: 2px; left: 50%; transform: translateX(-50%);
  width: 1px; height: 3px; background: currentColor;
}

.selection-panel {
  position: absolute;
  left: max(18px, env(safe-area-inset-left));
  bottom: 142px;
  width: 312px;
  padding: 13px 14px 12px;
  background:
    linear-gradient(135deg, rgba(31,35,23,.94), rgba(16,19,12,.92)),
    repeating-linear-gradient(0deg, transparent 0 3px, rgba(255,255,255,.02) 3px 4px);
  border: 1px solid rgba(214,194,151,.23);
  box-shadow: 0 18px 50px rgba(0,0,0,.38), inset 0 1px 0 rgba(255,246,220,.06);
  backdrop-filter: blur(9px);
  animation: panel-in .22s ease;
}
@keyframes panel-in { from { opacity: 0; transform: translateY(8px); } }
.selection-panel:before {
  content: ""; position: absolute; left: -1px; top: 13px; bottom: 13px; width: 2px;
  background: linear-gradient(to bottom, transparent, var(--gold), transparent);
}
.sel-head { display: flex; gap: 10px; align-items: center; }
.sel-icon {
  width: 39px; height: 39px;
  flex: 0 0 auto;
  border: 1px solid rgba(214,194,151,.26);
  background: rgba(0,0,0,.18);
  display: grid;
  place-items: center;
  color: var(--gold);
}
.sel-icon svg { width: 28px; height: 28px; }
.sel-kicker {
  display: block;
  color: var(--gold);
  font-family: var(--sans);
  font-size: 7px;
  letter-spacing: .22em;
  text-transform: uppercase;
  margin-bottom: 3px;
}
.sel-head h2 {
  font-size: 16px;
  font-weight: 500;
  margin: 0;
  letter-spacing: .015em;
  color: #f2e9d3;
}
.close-sel {
  margin-left: auto;
  border: 0;
  background: transparent;
