() => {
  const g = window.game;
  g.paused = false;
  g.selection.clear();
  g.playerUnits.forEach(u => { if (!u.dead && !u.routing) g.selection.add(u); });
  g.refreshSelection();
  const log = [];
  const dt = 0.05;
  let steps = 0;
  const snap = (label) => log.push({
    label, t: +g.time.toFixed(1), over: g.over,
    frMorale: +g.armyMorale(g.units.filter(u => u.side === 'fr')).toFixed(1),
    gbMorale: +g.armyMorale(g.units.filter(u => u.side === 'gb')).toFixed(1),
    frLeft: g.playerUnits.reduce((n,u)=>n+u.aliveCount,0),
    gbLeft: g.enemyUnits.reduce((n,u)=>n+u.aliveCount,0),
    cap: +g.capture.progress.toFixed(0), taken: g.capture.taken, hold: +g.capture.hold.toFixed(0),
    frRouting: g.playerUnits.filter(u=>u.routing).map(u=>u.short),
    gbRouting: g.enemyUnits.filter(u=>u.routing).map(u=>u.short)
  });
  for (let block = 0; block < 80; block++) {
    // reissue a plausible combined-arms push every 10 seconds
    if (!g.over) {
      const target = g.units.find(u => u.side === 'gb' && !u.dead && !u.routing &&
        (u.short === 'Foot Guards' || u.short === '33rd Foot' || u.short === '42nd Foot')) ||
        g.units.find(u => u.side === 'gb' && !u.dead && !u.routing);
      if (target) g.issueAttack(target);
    }
    for (let i = 0; i < 200; i++) {
      g.update(dt);
      steps++;
      if (g.over) break;
    }
    if (block % 3 === 0 || g.over) snap('block'+block);
    if (g.over) break;
  }
  return { steps, log, result: g.over ? (g.el.resultTitle.textContent + ' / ' + g.el.resultKicker.textContent) : 'still fighting' };
}
EOF
