() => {
  const g = window.game;
  const c = document.getElementById('battlefield');
  const u = g.playerUnits[1];
  const sx = (u.x - g.camera.x) * g.camera.zoom + g.vw/2;
  const sy = (u.y - g.camera.y) * g.camera.zoom + g.vh/2;
  const fire = (type, id, x, y) => c.dispatchEvent(new PointerEvent(type, {pointerId:id, pointerType:'touch', clientX:x, clientY:y, bubbles:true, cancelable:true, button:0}));
  fire('pointerdown', 1, sx, sy);
  fire('pointerup', 1, sx, sy);
  const selected = g.selection.has(u);
  const before = {x:u.dest?.x, y:u.dest?.y};
  fire('pointerdown', 2, 300, 430);
  fire('pointerup', 2, 300, 430);
  const after = {x:u.dest?.x, y:u.dest?.y};
  // pinch: two fingers spread apart
  const z0 = g.camera.zoom;
  fire('pointerdown', 3, 140, 380);
  fire('pointerdown', 4, 240, 380);
  fire('pointermove', 3, 100, 380);
  fire('pointermove', 4, 280, 380);
  const z1 = g.camera.zoom;
  fire('pointerup', 3, 100, 380);
  fire('pointerup', 4, 280, 380);
  return {sx:+sx.toFixed(0), sy:+sy.toFixed(0), selected, before, after, zoomBefore:+z0.toFixed(2), zoomAfter:+z1.toFixed(2)};
}
