  const g = window.game;
  g.paused=false;
  const fr = g.playerUnits.filter(u => ['line','light','guard'].includes(u.type));
  const gb = g.enemyUnits.filter(u => ['line','guard','light'].includes(u.type));
  // Stage two lines at volley distance for a clean smoke study.
  fr.forEach((u,i) => { u.x = 980 + i*120; u.y = 900; u.angle = Math.PI; u.target = gb[i % gb.length]; u.cooldown = 0; });
  gb.forEach((u,i) => { u.x = 980 + i*110; u.y = 640; u.angle = 0; u.target = fr[i % fr.length]; u.cooldown = 0; });
  for (const u of [...fr, ...gb]) {
    for (const s of u.soldiers) { s.x = u.x + (Math.random()-.5)*40; s.y = u.y + (Math.random()-.5)*18; s.angle = u.angle; }
    u.fireAt(u.target, g);
  }
  for (let i=0;i<14;i++) g.update(0.05);
  g.paused = true;
  document.getElementById('pause-wash').classList.add('hidden');
  g.camera.x=g.camera.tx=1170; g.camera.y=g.camera.ty=790; g.camera.zoom=g.camera.tz=1.1;
