cat > /tmp/sim5.js <<'EOF'
() => {
  const g = window.game;
  g.paused = false;
  g.selection.clear();
  g.playerUnits.forEach(u => { if (!u.dead && !u.routing) g.selection.add(u); });
  g.refreshSelection();
  const log = [];
  const snap = (label) => log.push({
    label, t:+g.time.toFixed(1), over:g.over,
    frMorale:+g.armyMorale(g.playerUnits).toFixed(1), gbMorale:+g.armyMorale(g.enemyUnits).toFixed(1),
    frLeft:g.playerUnits.reduce((n,u)=>n+u.aliveCount,0), gbLeft:g.enemyUnits.reduce((n,u)=>n+u.aliveCount,0),
    cap:+g.capture.progress.toFixed(0), taken:g.capture.taken, hold:+g.capture.hold.toFixed(0),
    frRouting:g.playerUnits.filter(u=>u.routing).map(u=>u.short), gbRouting:g.enemyUnits.filter(u=>u.routing).map(u=>u.short)
  });
  const assign = () => {
    const enemies = g.enemyUnits.filter(u=>!u.dead&&!u.routing);
    for (const u of g.playerUnits) {
      if (u.dead||u.routing) continue;
      if (u.type === 'arty') {
        const e = enemies.find(x=>x.type==='arty') || enemies[0];
        if (e) u.setAttack(e);
      } else {
        const e = enemies.slice().sort((a,b)=>u.distanceTo(a)-u.distanceTo(b))[0];
        if (e) u.setAttack(e);
      }
    }
  };
  for (let block=0; block<24; block++) {
    if (!g.over) assign();
    for (let i=0;i<200;i++){ g.update(0.05); if(g.over) break; }
    if (block%3===0||g.over) snap('b'+block);
    if (g.over) break;
  }
  return {time:+g.time.toFixed(1), log, result:g.over?g.el.resultTitle.textContent+' / '+g.el.resultKicker.textContent:'fighting'};
}
EOF
for i in 1 2 3; do playwright-cli -s=game reload >/dev/null 2>&1; sleep 2.5; echo "RUN $i"; playwright-cli -s=game eval "$(cat /tmp/sim5.js)" 2>&1 | grep -E '"time"|"result"|"t":|"frLeft"|"gbLeft"|"frMorale"|"gbMorale"|"taken"' | tail -22; done

